from pathlib import Path
p=Path('outputs/qa')
s=(p/'verify-device-lighting.cjs').read_text(encoding='utf8')
s=s.replace("lightQA.setQuiet();lightQA.sync(lightQA.idle);lightQA.step(9000);", "lightQA.sync(lightQA.idle);lightQA.step(9000);")
s=s.replace("const samples=[];", "await page.addStyleTag({content:'.home-device-rig{transform:none!important}'});\n   const samples=[];")
s=s.replace("'device-lighting-before.json'", "'device-lighting-before.json'")
s=s.replace('`device-lighting-${width}', '`device-blue-${width}')
s=s.replace("'device-lighting-'+", "'device-blue-'+")
s=s.replace('`device-lighting-live-${state}', '`device-blue-live-${state}')
s=s.replace("'device-lighting-live.json'", "'device-blue-live.json'")
s=s.replace("const samples=[];", "const samples=[];")
s=s.replace(".long,.48)",".long,.68)")
s=s.replace(".long,.34)",".long,.64)")
s=s.replace("assert(samples.find(s=>s.state==='pulse').short.every(n=>n>.48));", "assert(samples.find(s=>s.state==='pulse').short.every(n=>n===.68));assert(samples.find(s=>s.state==='pulse').moving>.9);")
s=s.replace("assert(samples.find(s=>s.state==='boost').long>.85);", "assert(samples.find(s=>s.state==='boost').moving>.9);")
s=s.replace("assert.equal(samples.find(s=>s.state==='claim').long,.8);", "assert(samples.find(s=>s.state==='claim').moving>.9);")
s=s.replace("short:[...document.querySelectorAll('.craft-short-light')]", "coreColor:getComputedStyle(document.querySelector('.craft-long-light')).fill,pulseColor:getComputedStyle(document.querySelector('.craft-pulse-slice')).stroke,blend:getComputedStyle(document.querySelector('.home-device-lights')).mixBlendMode,short:[...document.querySelectorAll('.craft-short-light')]")
s=s.replace("samples.push(sample);", "assert.equal(sample.coreColor,'rgb(72, 207, 255)');assert.equal(sample.pulseColor,'rgb(161, 234, 255)');assert.equal(sample.blend,'normal');samples.push(sample);")
s=s.replace("long:+document.querySelector('.craft-long-light').style.opacity,status:","long:+document.querySelector('.craft-long-light').style.opacity,moving:+document.querySelector('.craft-travelling-light').style.opacity,status:")
s=s.replace("assert((await sample('boost')).long>.6);", "assert((await sample('boost')).moving>.9);")
s=s.replace("assert(claim.long>.35);", "assert(claim.moving>.85);")
# Always close the browser even when an assertion fails.
s=s.replace("const results=[];", "try {\n const results=[];")
s=s.replace("await browser.close();", "} finally { await browser.close(); }")
(p/'verify-device-blue.cjs').write_text(s,encoding='utf8')
pix=(p/'check-device-lighting-pixels.py').read_text(encoding='utf8').replace('device-lighting-','device-blue-')
pix=pix.replace('(x-6)', '(x-16)').replace('(x+n+6)', '(x+n+16)').replace('(y-6)', '(y-16)').replace('(y+7)', '(y+17)').replace('Six source pixels','Sixteen source pixels')
(p/'check-device-blue-pixels.py').write_text(pix,encoding='utf8')
